  {
   "code": "SAMPLE_SIZE_POWER",
   "text": "Many specific five-player lineups will have limited minutes played, leading to low sample sizes and insufficient power for robust comparisons, especially when controlling for other factors."
  },
  {
   "code": "CONFOUNDING",
   "text": "Lineup changes are not random; coaches make substitutions for strategic reasons (e.g., opponent, game situation, fatigue, foul trouble, performance). These factors could confound the observed changes in shot mix with the personnel effects."
  },
  {
   "code": "MEASURE_RELIABILITY",
   "text": "The 'shot mix' concept needs precise definition. If using 'play-type mix', the reliability and validity of the rule-based classifier for play types (the 'inferrer') is a factor. If using 'shot distance mix', it's more direct but still needs clear binning/categorization."
  },
  {
   "code": "DRIFT_NONSTATIONARITY",
   "text": "Team strategies, player roles, and shot mixes can evolve over a season and across the three seasons of data available. This temporal drift could complicate comparisons of lineups if not accounted for."
  }
 ],
 "predicted_outcome": {
  "supported": 0.6,
  "rejected": 0.1,
  "untestable": 0.1,
  "artifact": 0.1,
  "uncertain": 0.1
 },
 "decision": "proceed_with_changes",
 "design": {
  "estimand": "The causal effect of a specific five-player offensive lineup on the team's subsequent play-type mix (distribution of possession-level play types) over a defined period (e.g., a game or season segment). The goal is to demonstrate that a design can detect such effects.",
  "unit": "Possession. Each unit will be associated with the offensive five-player lineup on the court at the start of the possession.",
  "sample": "All non-garbage time possessions from NBA 2022-23, 2023-24, and 2024-25 regular season games. Playoff games will be excluded to maintain consistency and avoid specialized strategic variations. Minimum thresholds for lineup minutes (e.g., 100 minutes per lineup) will be applied to ensure adequate sample size for comparisons.",
  "power": "Power will be assessed by simulating data based on observed variance in play-type mixes and expected effect sizes of personnel changes. The primary goal is to demonstrate a statistically significant difference (p < 0.05) in at least one play-type proportion between meaningfully different lineups, given sufficient minutes. Minimum detectable effect sizes will be calculated for key play types.",
  "controls": "The analysis will control for game-level factors such as opponent, score differential, and game clock using fixed effects for game segments (e.g., quarter, or game state bins). Team-level fixed effects will be used to compare lineups within the same team. Player-level fixed effects for individual players may also be considered to isolate the marginal effect of a specific player within a lineup. To mitigate confounding from non-random substitutions, a regression discontinuity approach could be explored around substitution events, or a matching approach based on pre-substitution game state.",
  "falsification": "A falsification test could involve analyzing the 'shot mix' of the *defensive* five against changes in offensive personnel, which should ideally show no or minimal direct effect, as the defensive five's composition should primarily affect defensive outcomes, not directly dictate the opponent's offensive play-type mix (though indirect effects via matchup are possible). Another falsification could be to randomly shuffle lineup assignments within a team and verify that no significant effects are detected.",
  "multiplicity": "Multiple hypothesis testing will be addressed using a False Discovery Rate (FDR) control procedure (e.g., Benjamini-Hochberg) for the different play types being analyzed. The primary outcome will be the detection of *any* significant change in play-type mix, rather than specific play types, to reduce the family-wise error rate for the 'design validation' goal.",
  "decision_rule": "The design will be considered successful if statistically significant differences (p < 0.05 after FDR correction) in at least one major play-type proportion are consistently detected between distinct and sufficiently-minuted offensive five-player lineups for a substantial number of teams, after accounting for confounding factors. This would indicate the design's ability to 'detect personnel effects'.",
  "data_version": "NBA 2022-23, 2023-24, 2024-25 regular season play-by-play, substitution rotation, and derived play-type possession records."
 }
}

